"""Verifier for quarterly-revenue-by-region. Generated by scripts/build_harbor_tasks.py.

S1 cheap artifact checks, S2 content checks on the manifest of a re-run of
plot.py, S3 delivered PNG == fresh render, S5 sidecar against the answer key.
Machinery: verifier_core.py (adapted from harbor/example/tests/test_state.py).

Known blind spots (the point of the second mutant): nothing here measures
legibility -- tick-label rotation, overlap, clipping at the image edge, or
contrast -- and line dash patterns and legend placement are only partly checked.
"""

from pathlib import Path

import pytest

from verifier_core import (
    APP, DELIVERED_FIGURE, assert_close, axes, bar_containers, check_input_unchanged,
    check_rerender_matches, check_valid_nonblank_png, delivered, find_script, lines,
    load_sidecar, norm_colour, snapshot_delivered, reexecute,
)

INPUTS = {"transactions.csv": "6d300a4be1145cfead8ef172352cce983101409b2d2d87836d8cbc6042c4f74b"}


@pytest.fixture(scope="session")
def manifest():
    snapshot_delivered()
    return reexecute(Path("/tmp/reexec"))


def test_s1_figure_is_a_valid_nonblank_png():
    snapshot_delivered()
    check_valid_nonblank_png()


def test_s1_inputs_unchanged():
    for name, digest in INPUTS.items():
        check_input_unchanged(name, digest)


def test_s1_plotting_script_left_behind():
    assert find_script().stat().st_size > 0


def test_s3_delivered_png_matches_a_fresh_render(manifest):
    check_rerender_matches(manifest)


def png_size():
    from PIL import Image

    with Image.open(delivered(DELIVERED_FIGURE)) as image:
        return image.size

REGIONS = ["East", "North", "South", "West"]
QUARTERS = ["Q1", "Q2", "Q3", "Q4"]
# revenue = units * unit_price, summed per region and calendar quarter, / 1000.
# Near miss (mutants/sum_units, summing units): East 2694, 2357, 2403, 2656 ...
KEY = {"East": [74.732, 67.617, 65.329, 70.741], "North": [74.673, 76.761, 88.875, 87.535], "South": [60.907, 58.318, 54.662, 51.873], "West": [49.093, 48.628, 52.251, 57.958]}
TOL = 0.05


def test_s5_sidecar_matches_key():
    declared = load_sidecar()
    assert sorted(declared) == REGIONS, f"sidecar keys {sorted(declared)}"
    for region in REGIONS:
        assert_close(declared[region], KEY[region], TOL, f"plotted_values.json[{region!r}]")


def test_s2_sixteen_vertical_bars_with_the_right_heights(manifest):
    bars = [c for c in bar_containers(manifest) if c.get("orientation") == "vertical"]
    by_label = {c.get("label"): c for c in bars}
    assert set(REGIONS) <= set(by_label), f"bar series labelled {sorted(by_label)}, expected the four regions"
    for region in REGIONS:
        container = by_label[region]
        ordered = [v for _, v in sorted(zip(container["offsets"], container["values"]))]
        assert_close(ordered, KEY[region], TOL, f"{region} bars, Q1..Q4")


def test_s2_regions_alphabetical_within_each_quarter(manifest):
    bars = {c.get("label"): c for c in bar_containers(manifest)}
    for q in range(4):
        offsets = [sorted(bars[region]["offsets"])[q] for region in REGIONS]
        assert offsets == sorted(offsets), f"{QUARTERS[q]}: regions not left-to-right East, North, South, West"


def test_s2_axes_text_limits_and_legend(manifest):
    ax = axes(manifest)
    assert [t for t in ax["xticklabels"] if t.strip()] == QUARTERS
    assert ax["xlabel"] == "Quarter of 2025"
    assert ax["ylabel"] == "Revenue (thousand USD)"
    assert ax["title"] == "Quarterly revenue by region, 2025"
    assert abs(ax["ylim"][0]) < 1e-9, f"y axis starts at {ax['ylim'][0]}, not 0"
    legend = ax.get("legend") or {}
    assert set(REGIONS) <= set(legend.get("labels", [])), "legend must name the four regions"


def test_s2_figure_is_10_by_6_inches_at_100_dpi():
    assert png_size() == (1000, 600), f"figure.png is {png_size()}, expected 1000x600"
